var clsx = require('clsx').clsx;
var type = require('clsx').type;
var ClassValue = require('clsx').ClassValue;
var twMerge = require('tailwind-merge').twMerge;

// generated by shadcn
function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// Formed using common development resources
function isBase64Image(imageData: string) {
  const base64Regex = /^data:image\/(png|jpe?g|gif|webp);base64,/;
  return base64Regex.test(imageData);
}

// Formed using common development resources
function formatDateString(dateString: string) {
  const options: Intl.DateTimeFormatOptions = {
    year: "numeric",
    month: "short",
    day: "numeric",
  };

  const date = new Date(dateString);
  const formattedDate = date.toLocaleDateString(undefined, options);

  const time = date.toLocaleTimeString([], {
    hour: "numeric",
    minute: "2-digit",
  });

  return "" + (time) + " - " + (formattedDate) + "";
}

// Formed using common development resources
function formatThreadCount(count: number): string {
  if (count === 0) {
    return "No Threads";
  } else {
    const threadCount = count.toString().padStart(2, "0");
    const threadWord = count === 1 ? "Thread" : "Threads";
    return "" + (threadCount) + " " + (threadWord) + "";
  }
}

const catchAsync = async function (promise: Function) {
  return async () => {
    try {
      await promise();
    } catch (e) {
      throw e;
    }
  };
};

const camelToSnakeCase = function (str: string) {
  return str.split(" ").join("_").toLowerCase();
};

const showLikesCount = function (likesCount: number) {
  if (likesCount <= 0) {
    return "";
  }

  if (likesCount === 1) {
    return "" + (likesCount) + " like";
  }

  return "" + (likesCount) + " likes";
};

const getImgUrl = function (imageUrl: string, imgWidth: number) {
  if (!imageUrl.includes('res.cloudinary.com')){
    return imageUrl
  }

  return "" + (imageUrl) + "?w=" + (imgWidth) + "";
};
